import unittest
from candidate import encode_cyclic, decode_cyclic

class TestEncodeDecodeCyclic(unittest.TestCase):
    def test_encode_cyclic_normalcase(self):
        self.assertEqual(encode_cyclic("abcdef"), "defabc")

    def test_encode_cyclic_empty_string(self):
        self.assertEqual(encode_cyclic(""), "")

    def test_encode_cyclic_fewer_than_three_characters(self):
        self.assertEqual(encode_cyclic("ab"), "ab")

    def test_encode_cyclic_more_than_three_characters(self):
        self.assertEqual(encode_cyclic("abcdef"), "defabc")

    def test_decode_cyclic_normalcase(self):
        self.assertEqual(decode_cyclic("defabc"), "abcdef")

    def test_decode_cyclic_empty_string(self):
        self.assertEqual(decode_cyclic(""), "")

    def test_decode_cyclic_same_as_input(self):
        self.assertEqual(decode_cyclic("abcdefabcdef"), "abcdefabcdef")

    def test_decode_cyclic_one_cycle(self):
        self.assertEqual(decode_cyclic("defabc"), "abcdef")

    def test_decode_cyclic_invalid_cyclic(self):
        with self.assertRaises(TypeError):
            decode_cyclic(123)

    def test_decode_cyclic_noncyclic(self):
        with self.assertRaises(TypeError):
            decode_cyclic("abcdef")

    def test_decode_cyclic_more_than_one_cycle(self):
        with self.assertRaises(TypeError):
            decode_cyclic(encode_cyclic("abcdef", cycle=2))

    def test_decode_cyclic_edge_case_cycle_one(self):
        self.assertEqual(decode_cyclic("defabcdef"), "abcdefabcdef")
